SELECT


WHERE b.deleted = 0

    AND b.user_id = #{userId}


    AND b.craftsman_id = #{craftsmanId}


    AND b.status = #{q.status}


    AND b.course_id = #{q.courseId}


    AND (
        b.booking_no    LIKE CONCAT('%', #{q.keyword}, '%')
        OR c.title      LIKE CONCAT('%', #{q.keyword}, '%')
        OR b.contact_name LIKE CONCAT('%', #{q.keyword}, '%')
    )


    AND b.status = 0
    AND b.create_time <= DATE_SUB(NOW(), INTERVAL #{timeoutHours} HOUR)



    AND c.end_time >= NOW()

ORDER BY b.id DESC

SELECT


WHERE b.deleted = 0

    AND b.status = #{q.status}


    AND b.course_id = #{q.courseId}


    AND b.user_id = #{q.userId}


    AND b.craftsman_id = #{q.craftsmanId}


    AND (b.booking_no    LIKE CONCAT('%', #{q.keyword}, '%')
    OR b.contact_name    LIKE CONCAT('%', #{q.keyword}, '%')
    OR b.contact_phone   LIKE CONCAT('%', #{q.keyword}, '%')
    OR c.title           LIKE CONCAT('%', #{q.keyword}, '%')
    OR cr.real_name      LIKE CONCAT('%', #{q.keyword}, '%'))


    AND b.create_time >= #{q.startTime}


    AND b.create_time <= #{q.endTime}


    AND b.status = 0
    AND b.create_time <= DATE_SUB(NOW(), INTERVAL #{timeoutHours} HOUR)


    ORDER BY b.create_time ASC, b.id ASC
    ORDER BY c.start_time ASC, b.id DESC
    ORDER BY b.create_time DESC, b.id DESC
